package main

import (
	"path/filepath"
	"text/template"
)

var packageTemplate = template.Must(template.New("").Parse(`// Copyright (C) 2019-2026 GoRE Authors
//
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

// Code generated by go generate; DO NOT EDIT.
// This file was generated at
// {{ .Timestamp }}
// Generate with version hash: {{ .Hash }}

package gore

var stdPkgs = map[string]struct{}{
{{- range .StdPkg }}
	{{ printf "\"%s\": {}" . }},
{{- end }}
}
`))

var goversionTemplate = template.Must(template.New("").Parse(`// Copyright (C) 2019-2026 GoRE Authors
//
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

// Code generated by go generate; DO NOT EDIT.
// This file was generated at
// {{ .Timestamp }}

package gore

var goversions = map[string]*GoVersion{
{{- range .GoVersions }}
	{{ printf "\"%s\": {Name: \"%s\", SHA: \"%s\", Timestamp: \"%s\"}" .Name .Name .Sha .Date }},
{{- end }}
}
`))

const moduleDataHeader = `// Copyright (C) 2019-2026 GoRE Authors
//
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

// Code generated by go generate; DO NOT EDIT.

package gore

import (
	"fmt"
	"sort"
)

`

var (
	goversionCsv         = filepath.Join(getSourceDir(), "resources", "goversions.csv")
	stdpkgOutputFile     = filepath.Join(getSourceDir(), "stdpkg_gen.go")
	goversionOutputFile  = filepath.Join(getSourceDir(), "goversion_gen.go")
	moduleDataOutputFile = filepath.Join(getSourceDir(), "moduledata_gen.go")

	repoCacheFile = filepath.Join(getSourceDir(), "gen", ".go-repo-cache")
)
